==== heroes/heroes.view-model.ts
import { computed, Injectable, inject, signal } from '@angular/core';
import type { BadgeVariants } from '@spartan-ng/helm/badge';
import { POWER_CLASSES, type HeroStatus } from '../domain/hero.model';
import { HeroService } from '../domain/hero.service';

export interface RosterRow {
  readonly id: string;
  readonly name: string;
  readonly alias: string;
  readonly initials: string;
  readonly powerClass: string;
  readonly powerIndex: number;
  readonly status: HeroStatus;
  readonly statusVariant: BadgeVariants['variant'];
  readonly clearance: string;
}

export interface ClassOption {
  readonly value: string;
  readonly label: string;
}

const ALL_CLASSES = 'all';

const STATUS_VARIANT: Readonly<Record<HeroStatus, BadgeVariants['variant']>> = {
  Active: 'success',
  Injured: 'warning',
  Reserve: 'secondary',
  MIA: 'destructive',
};

@Injectable() // no providedIn: scoped to the Heroes component that provides it
export class HeroesViewModel {
  private readonly heroService = inject(HeroService);

  readonly query = signal('');
  readonly powerClass = signal(ALL_CLASSES);

  readonly classOptions: readonly ClassOption[] = [
    { value: ALL_CLASSES, label: 'All classes' },
    ...POWER_CLASSES.map((powerClass) => ({ value: powerClass, label: powerClass })),
  ];

  readonly total = computed(() => this.heroService.list().length);

  // Filtered by the search text and class, sorted by power (highest first).
  readonly rows = computed<readonly RosterRow[]>(() => {
    const needle = this.query().trim().toLowerCase();
    const powerClass = this.powerClass();

    return this.heroService
      .list()
      .filter((hero) => powerClass === ALL_CLASSES || hero.powerClass === powerClass)
      .filter(
        (hero) =>
          needle === '' ||
          [hero.name, hero.alias, hero.id].some((field) => field.toLowerCase().includes(needle)),
      )
      .sort((a, b) => b.powerIndex - a.powerIndex)
      .map((hero) => ({
        id: hero.id,
        name: hero.name,
        alias: hero.alias,
        initials: hero.name
          .split(/\s+/)
          .filter(Boolean)
          .slice(0, 2)
          .map((word) => word[0]?.toUpperCase() ?? '')
          .join(''),
        powerClass: hero.powerClass,
        powerIndex: hero.powerIndex,
        status: hero.status,
        statusVariant: STATUS_VARIANT[hero.status],
        clearance: hero.clearance,
      }));
  });

  classLabel = (value: string): string =>
    this.classOptions.find((option) => option.value === value)?.label ?? '';

  setQuery(query: string): void {
    this.query.set(query);
  }

  setPowerClass(value: string | null | undefined): void {
    this.powerClass.set(value ?? ALL_CLASSES);
  }
}
==== heroes/heroes.html
<section class="heroes">
  <header class="heroes__header">
    <h1 hlmH1>Roster</h1>
    <p hlmMuted>Example data. Every hero on the books, strongest first.</p>
  </header>

  <div class="heroes__filters" role="search">
    <label hlmLabel for="roster-search" class="heroes__label">Search heroes</label>
    <input
      hlmInput
      #search
      id="roster-search"
      type="search"
      placeholder="Search name, alias or ID"
      class="heroes__search"
      (input)="vm.setQuery(search.value)"
    />

    <label hlmLabel for="roster-class" class="heroes__label">Power class</label>
    <hlm-select
      class="heroes__class"
      [itemToString]="vm.classLabel"
      [value]="vm.powerClass()"
      (valueChange)="vm.setPowerClass($event)"
    >
      <hlm-select-trigger buttonId="roster-class" class="heroes__class-trigger">
        <hlm-select-value placeholder="All classes" />
      </hlm-select-trigger>
      <hlm-select-content *hlmSelectPortal>
        @for (option of vm.classOptions; track option.value) {
          <hlm-select-item [value]="option.value">{{ option.label }}</hlm-select-item>
        }
      </hlm-select-content>
    </hlm-select>

    <a hlmBtn routerLink="/recruit" class="heroes__recruit">
      <ng-icon hlmIcon name="lucideUserPlus" />
      Recruit
    </a>
  </div>

  <!-- At 375px the table scrolls inside its own container; the page itself does not. -->
  <div hlmTableContainer class="heroes__table-wrap">
    <table hlmTable aria-label="Hero roster">
      <thead hlmTHead>
        <tr hlmTr>
          <th hlmTh>Hero</th>
          <th hlmTh>Class</th>
          <th hlmTh>Power</th>
          <th hlmTh>Status</th>
          <th hlmTh>Clearance</th>
          <th hlmTh><span class="heroes__label">Actions</span></th>
        </tr>
      </thead>
      <tbody hlmTBody>
        @for (row of vm.rows(); track row.id) {
          <tr hlmTr>
            <td hlmTd>
              <div class="heroes__hero">
                <hlm-avatar>
                  <span hlmAvatarFallback>{{ row.initials }}</span>
                </hlm-avatar>
                <div class="heroes__identity">
                  <span hlmSmall>{{ row.name }}</span>
                  <span hlmMuted>{{ row.id }}</span>
                </div>
              </div>
            </td>
            <td hlmTd><span hlmBadge variant="outline">{{ row.powerClass }}</span></td>
            <td hlmTd>{{ row.powerIndex }}</td>
            <td hlmTd><span hlmBadge [variant]="row.statusVariant">{{ row.status }}</span></td>
            <td hlmTd>{{ row.clearance }}</td>
            <td hlmTd>
              <div class="heroes__actions">
                <a
                  hlmBtn
                  variant="ghost"
                  size="icon"
                  [routerLink]="['/detail', row.id]"
                  [attr.aria-label]="'Edit ' + row.name"
                >
                  <ng-icon hlmIcon name="lucidePencil" />
                </a>
              </div>
            </td>
          </tr>
        } @empty {
          <tr hlmTr>
            <td hlmTd colspan="6" class="heroes__empty">No heroes match these filters.</td>
          </tr>
        }
      </tbody>
      <tfoot hlmTFoot>
        <tr hlmTr>
          <td hlmTd colspan="6">
            <div class="heroes__summary">
              <span hlmSmall>{{ vm.rows().length }} of {{ vm.total() }} heroes</span>
              <span hlmMuted>sorted by power</span>
            </div>
          </td>
        </tr>
      </tfoot>
    </table>
  </div>
</section>

