    HlmButton,
    HlmBadge,
    HlmH1,
    HlmH2,
    HlmMuted,
    StatTile,
    HeroCard,
  ],
  providers: [DashboardViewModel, provideIcons({ lucideUserPlus })],
  templateUrl: './dashboard.html',
  styleUrl: './dashboard.css',
})
