import { z } from 'zod';
import { POWER_CLASSES } from '../domain/hero.model';

// Edit-form schema for the hero detail screen. The schema is the single source of
// truth for shape, rules, and field labels; the form reads labels off `.meta()`.
export const heroEditSchema = z.object({
  name: z.string().trim().min(1, 'Name is required').max(60).meta({
    label: 'Name',
    control: 'text',
    order: 1,
  }),
  alias: z.string().trim().min(1, 'Alias is required').max(60).meta({
    label: 'Alias',
    control: 'text',
    order: 2,
  }),
  powerClass: z.enum(POWER_CLASSES).meta({
