.hero-detail__tab-strip { @apply max-w-full overflow-x-auto; }
.hero-detail__panel { @apply grid min-w-0 gap-4; }

.hero-detail__overview { @apply grid grid-cols-1 gap-6 lg:grid-cols-2; }
.hero-detail__summary { @apply grid min-w-0 content-start gap-4; }
