import { HlmTabsImports } from '@spartan-ng/helm/tabs';
import { HlmTextareaImports } from '@spartan-ng/helm/textarea';
import { HlmH1, HlmH2, HlmLead, HlmMuted, HlmSmall } from '@spartan-ng/helm/typography';
import { HeroDetailViewModel } from './hero-detail.view-model';

@Component({
  selector: 'app-hero-detail',
  imports: [
    RouterLink,
    FormField,
    NgIcon,
    HlmIconImports,
    HlmAvatarImports,
    HlmBadge,
    HlmButton,
    HlmCardImports,
    HlmDialogImports,
    HlmFieldImports,
    HlmInput,
    HlmProgressImports,
    HlmSelectImports,
    HlmSwitchImports,
    HlmTabsImports,
    HlmTextareaImports,
    HlmH1,
    HlmH2,
    HlmLead,
    HlmMuted,
    HlmSmall,
  ],
  providers: [
    HeroDetailViewModel,
    provideIcons({ lucideChevronLeft, lucideCrosshair, lucideTrash2 }),
  ],
  templateUrl: './hero-detail.html',
  styleUrl: './hero-detail.css',
})
export class HeroDetail {
  protected readonly vm = inject(HeroDetailViewModel);
}

@reference "../../styles.css";

.hero-detail { @apply grid min-w-0 gap-6 p-4 sm:p-6; }
.hero-detail__back { @apply justify-self-start; }

.hero-detail__header { @apply flex min-w-0 flex-wrap items-start justify-between gap-4; }
.hero-detail__identity { @apply flex min-w-0 flex-wrap items-center gap-4; }
.hero-detail__names { @apply grid min-w-0 gap-1; }
.hero-detail__title { @apply break-words; }
.hero-detail__badges { @apply flex flex-wrap gap-2; }
.hero-detail__actions { @apply flex flex-wrap items-center gap-2; }

.hero-detail__tabs { @apply grid min-w-0 gap-4; }
/* The tab strip is the one intentional scroll container, so a narrow phone scrolls the strip, not the page. */
.hero-detail__tab-strip { @apply max-w-full overflow-x-auto; }
.hero-detail__panel { @apply grid min-w-0 gap-4; }

.hero-detail__overview { @apply grid grid-cols-1 gap-6 lg:grid-cols-2; }
.hero-detail__summary { @apply grid min-w-0 content-start gap-4; }
.hero-detail__mini { @apply grid grid-cols-1 gap-3 sm:grid-cols-3; }
.hero-detail__mini-body { @apply grid gap-1; }
.hero-detail__dossier { @apply grid min-w-0 content-start gap-4; }
.hero-detail__facts { @apply grid gap-3; }
.hero-detail__fact { @apply grid min-w-0 gap-0.5; }

.hero-detail__powers { @apply grid grid-cols-1 gap-6 lg:grid-cols-2; }
.hero-detail__meters-section { @apply grid min-w-0 content-start gap-4; }
.hero-detail__meters { @apply grid gap-4; }
.hero-detail__meter { @apply grid min-w-0 gap-2; }
.hero-detail__meter-head { @apply flex flex-wrap items-baseline justify-between gap-2; }
.hero-detail__abilities-section { @apply grid min-w-0 content-start gap-4; }
.hero-detail__abilities { @apply flex flex-wrap gap-2; }

.hero-detail__missions { @apply grid min-w-0 gap-4; }
.hero-detail__deployments { @apply grid gap-2; }
.hero-detail__deployment { @apply flex flex-wrap items-center justify-between gap-2; }

.hero-detail__form { @apply grid min-w-0 gap-6; }
.hero-detail__fields { @apply grid grid-cols-1 gap-4 sm:grid-cols-2; }
.hero-detail__wide { @apply sm:col-span-2; }
.hero-detail__form-actions { @apply flex flex-wrap justify-end gap-2; }

.hero-detail__missing { @apply grid gap-2; }
